mapper.select:
SELECT p.id AS productId, COALESCE(s.soldQty, 0) AS salesCount, COALESCE(s.monthSoldQty, 0) AS monthSalesCount, COALESCE(f.favoriteQty, 0) AS favoriteCount, COALESCE(r.reviewQty, 0) AS reviewCount, COALESCE(r.ratingAvg, 0) AS ratingAvg FROM ck_shop_product p LEFT JOIN ( SELECT oi.product_id AS pid, SUM(oi.quantity - COALESCE(oi.refund_quantity, 0)) AS soldQty, SUM(CASE WHEN o.pay_time >= #{monthSince} THEN oi.quantity - COALESCE(oi.refund_quantity, 0) ELSE 0 END) AS monthSoldQty FROM ck_shop_order_item oi INNER JOIN ck_shop_order o ON o.id = oi.order_id WHERE o.del_flag = 0 -- PAID 与 PARTIAL_REFUND 都是"收过钱"；全额退款后订单会变成 CANCELLED/REFUNDED，自动掉出统计 AND o.pay_status IN ('PAID', 'PARTIAL_REFUND') AND o.order_status NOT IN ('CANCELLED', 'CLOSED') AND oi.product_id IN
#{pid}
GROUP BY oi.product_id ) s ON s.pid = p.id LEFT JOIN ( SELECT fa.product_id AS pid, COUNT(*) AS favoriteQty FROM ck_shop_favorite fa WHERE fa.del_flag = 0 AND fa.product_id IN
#{pid}
GROUP BY fa.product_id ) f ON f.pid = p.id LEFT JOIN ( SELECT rv.product_id AS pid, COUNT(*) AS reviewQty, ROUND(AVG(rv.rating), 1) AS ratingAvg FROM ck_shop_product_review rv WHERE rv.del_flag = 0 AND rv.status = 'Y' AND rv.product_id IN
#{pid}
GROUP BY rv.product_id ) r ON r.pid = p.id WHERE p.id IN
#{pid}
